package com.dns.resolver

import java.net.DatagramPacket
import java.net.DatagramSocket
import java.net.InetAddress
import java.security.SecureRandom
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import java.util.concurrent.atomic.AtomicLong
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec

class DnsQueryCache(
    private val encryptionKey: ByteArray,
    private val maxQueriesPerSecond: Int = 100
) {
    private val cache = ConcurrentHashMap<String, ByteArray>()
    private val queryCounter = AtomicInteger(0)
    private val windowStart = AtomicLong(System.currentTimeMillis())
    private val retryState = ConcurrentHashMap<String, RetryContext>()
    private val random = SecureRandom()

    data class RetryContext(
        val attempts: Int,
        val lastAttemptTime: Long,
        val sessionNonce: ByteArray,
        val sequenceCounter: AtomicInteger
    )

    private fun checkRateLimit(): Boolean {
        val now = System.currentTimeMillis()
        val start = windowStart.get()
        if (now - start > 1000) {
            windowStart.set(now)
            queryCounter.set(0)
        }
        return queryCounter.incrementAndGet() <= maxQueriesPerSecond
    }

    fun buildIv(context: RetryContext): ByteArray {
        val iv = ByteArray(12)
        // Copy 8-byte session nonce into first 8 bytes
        System.arraycopy(context.sessionNonce, 0, iv, 0, 8)
        // Use sequence counter for last 4 bytes
        val seq = context.sequenceCounter.getAndIncrement()
        iv[8] = (seq shr 24).toByte()
        iv[9] = (seq shr 16).toByte()
        iv[10] = (seq shr 8).toByte()
        iv[11] = seq.toByte()
        return iv
    }

    fun encryptCacheEntry(domain: String, responseData: ByteArray): ByteArray {
        val context = retryState.getOrPut(domain) {
            val nonce = ByteArray(8)
            random.nextBytes(nonce)
            RetryContext(
                attempts = 0,
                lastAttemptTime = System.currentTimeMillis(),
                sessionNonce = nonce,
                sequenceCounter = AtomicInteger(0)
            )
        }

        val iv = buildIv(context)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val keySpec = SecretKeySpec(encryptionKey, "AES")
        val gcmSpec = GCMParameterSpec(128, iv)
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)
        cipher.updateAAD(domain.toByteArray(Charsets.UTF_8))
        return cipher.doFinal(responseData)
    }

    fun resolveWithRetry(domain: String, dnsServer: String = "8.8.8.8", maxRetries: Int = 3): ByteArray? {
        if (!checkRateLimit()) {
            throw RateLimitExceededException("Query rate limit exceeded")
        }

        val cached = cache[domain]
        if (cached != null) return cached

        var lastException: Exception? = null
        val context = retryState.getOrPut(domain) {
            val nonce = ByteArray(8)
            random.nextBytes(nonce)
            RetryContext(
                attempts = 0,
                lastAttemptTime = System.currentTimeMillis(),
                sessionNonce = nonce,
                sequenceCounter = AtomicInteger(0)
            )
        }

        for (attempt in 0 until maxRetries) {
            try {
                val response = performDnsQuery(domain, dnsServer)
                val encrypted = encryptCacheEntry(domain, response)
                cache[domain] = encrypted
                return encrypted
            } catch (e: Exception) {
                lastException = e
                // On retry, counter was already incremented in buildIv
                Thread.sleep(calculateBackoff(attempt))
            }
        }

        throw DnsResolutionException("Failed after $maxRetries attempts", lastException)
    }

    private fun calculateBackoff(attempt: Int): Long {
        return minOf(1000L * (1 shl attempt), 8000L)
    }

    private fun performDnsQuery(domain: String, server: String): ByteArray {
        val queryPacket = buildDnsQuery(domain)
        val socket = DatagramSocket()
        socket.soTimeout = 5000

        try {
            val address = InetAddress.getByName(server)
            val sendPacket = DatagramPacket(queryPacket, queryPacket.size, address, 53)
            socket.send(sendPacket)

            val buffer = ByteArray(512)
            val receivePacket = DatagramPacket(buffer, buffer.size)
            socket.receive(receivePacket)

            return buffer.copyOf(receivePacket.length)
        } finally {
            socket.close()
        }
    }

    private fun buildDnsQuery(domain: String): ByteArray {
        val transactionId = random.nextInt(0xFFFF)
        val header = byteArrayOf(
            (transactionId shr 8).toByte(), transactionId.toByte(),
            0x01, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
        )
        val question = encodeDomainName(domain) + byteArrayOf(0x00, 0x01, 0x00, 0x01)
        return header + question
    }

    private fun encodeDomainName(domain: String): ByteArray {
        val parts = domain.split(".")
        val result = mutableListOf<Byte>()
        for (part in parts) {
            val labelBytes = part.toByteArray(Charsets.UTF_8)
            // DNS label validation: each label must be non-empty (except trailing root)
            // and at most 63 octets. Values >= 64 corrupt the length octet since the
            // top two bits are reserved for compression pointers.
            if (labelBytes.isEmpty()) {
                throw IllegalArgumentException("Invalid domain name: empty label in '$domain'")
            }
            if (labelBytes.size > 63) {
                throw IllegalArgumentException("Invalid domain name: label exceeds 63 octets in '$domain'")
            }
            result.add(labelBytes.size.toByte())
            result.addAll(labelBytes.toList())
        }
        result.add(0x00)
        // Total encoded name (including length octets and root) must not exceed 255 octets.
        if (result.size > 255) {
            throw IllegalArgumentException("Invalid domain name: encoded name exceeds 255 octets in '$domain'")
        }
        return result.toByteArray()
    }

    fun decryptCacheEntry(domain: String, encryptedData: ByteArray): ByteArray {
        val context = retryState[domain] ?: throw IllegalStateException("No context for domain")
        // For decryption, we need the IV that was used during encryption
        // The counter was incremented atomically in buildIv, last used value is current - 1
        val decryptSeq = context.sequenceCounter.get() - 1
        val iv = ByteArray(12)
        System.arraycopy(context.sessionNonce, 0, iv, 0, 8)
        iv[8] = (decryptSeq shr 24).toByte()
        iv[9] = (decryptSeq shr 16).toByte()
        iv[10] = (decryptSeq shr 8).toByte()
        iv[11] = decryptSeq.toByte()

        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val keySpec = SecretKeySpec(encryptionKey, "AES")
        val gcmSpec = GCMParameterSpec(128, iv)
        cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec)
        cipher.updateAAD(domain.toByteArray(Charsets.UTF_8))
        return cipher.doFinal(encryptedData)
    }
}

class RateLimitExceededException(message: String) : Exception(message)
class DnsResolutionException(message: String, cause: Exception?) : Exception(message, cause)
